import{_ as e,c as t,o as d,a as o}from"./app.19f3f8f0.js";const m=JSON.parse('{"title":"Agent & contributor guide","description":"","frontmatter":{},"headers":[{"level":2,"title":"Related repositories","slug":"related-repositories","link":"#related-repositories","children":[]},{"level":2,"title":"Stack & boundaries","slug":"stack-boundaries","link":"#stack-boundaries","children":[]},{"level":2,"title":"Common commands","slug":"common-commands","link":"#common-commands","children":[]},{"level":2,"title":"Directory map","slug":"directory-map","link":"#directory-map","children":[]},{"level":2,"title":"Documents to read with reply-bridge","slug":"documents-to-read-with-reply-bridge","link":"#documents-to-read-with-reply-bridge","children":[]},{"level":2,"title":"Style","slug":"style","link":"#style","children":[]},{"level":2,"title":"Cursor rules (outside VitePress docs/)","slug":"cursor-rules-outside-vitepress-docs","link":"#cursor-rules-outside-vitepress-docs","children":[]}],"relativePath":"AGENT.md"}'),r={name:"AGENT.md"},i=o('<h1 id="agent-contributor-guide" tabindex="-1">Agent &amp; contributor guide <a class="header-anchor" href="#agent-contributor-guide" aria-hidden="true">#</a></h1><p>Facts only—for Cursor and other coding agents. Product and API truth live in the sibling <strong>reply-bridge</strong> repository first.</p><h2 id="related-repositories" tabindex="-1">Related repositories <a class="header-anchor" href="#related-repositories" aria-hidden="true">#</a></h2><table><thead><tr><th>Path</th><th>Role</th></tr></thead><tbody><tr><td><code>/Users/hojin/Work/tldr/reply-bridge</code></td><td>ReplyBridge app, server, marketing source. Use <code>marketing/</code> and <code>docs/</code> for copy, features, and screenshots.</td></tr><tr><td>This repo (<code>static-site</code>)</td><td><strong>VitePress</strong> public site (landing, blog, legal, per-app pages).</td></tr></tbody></table><p>If static-site and reply-bridge disagree, <strong>reply-bridge is closer to product truth</strong>—fix static-site.</p><h2 id="stack-boundaries" tabindex="-1">Stack &amp; boundaries <a class="header-anchor" href="#stack-boundaries" aria-hidden="true">#</a></h2><ul><li><strong>Build:</strong> <a href="https://vitepress.dev/" target="_blank" rel="noreferrer">VitePress</a> 1.x, <strong>Vue 3</strong> (theme/extensions).</li><li><strong>Source:</strong> <code>docs/</code> — Markdown pages; <code>docs/.vitepress/config.js</code> — site meta, nav, footer.</li><li><strong>Static assets:</strong> <code>docs/public/</code> (<code>ads.txt</code>, <code>app-ads.txt</code>, etc.).</li><li><strong>Deploy:</strong> <code>.github/workflows/main.yml</code>.</li></ul><h2 id="common-commands" tabindex="-1">Common commands <a class="header-anchor" href="#common-commands" aria-hidden="true">#</a></h2><p>Run from the <strong>repository root</strong>:</p><table><thead><tr><th>Goal</th><th>Command</th></tr></thead><tbody><tr><td>Local preview</td><td><code>npm run docs:dev</code></td></tr><tr><td>Production build</td><td><code>npm run docs:build</code></td></tr><tr><td>Preview build output</td><td><code>npm run docs:preview</code></td></tr></tbody></table><h2 id="directory-map" tabindex="-1">Directory map <a class="header-anchor" href="#directory-map" aria-hidden="true">#</a></h2><table><thead><tr><th>Path</th><th>Role</th></tr></thead><tbody><tr><td><code>docs/index.md</code>, etc.</td><td>Home, About, Services, legal hub</td></tr><tr><td><code>docs/blog/</code></td><td>Blog</td></tr><tr><td><code>docs/replybridge/</code></td><td>ReplyBridge — <code>getting-started</code>, overview, connect, usage, <code>series/</code> (Instagram mini-series, add <code>NN-slug.md</code> + sidebar), <code>marketing/</code></td></tr><tr><td><code>docs/*/</code> (e.g. <code>clubhouse/</code>, <code>slotspace/</code>)</td><td>Per-app subsites</td></tr><tr><td><code>docs/*-privacy-policy/</code>, <code>docs/*-term-conditions/</code></td><td>Per-app legal</td></tr><tr><td><code>docs/.vitepress/config.js</code></td><td><code>title</code>, <code>description</code>, <code>nav</code>, <code>footer</code>, <code>head</code>, <code>sidebar</code> (ReplyBridge)</td></tr></tbody></table><p>Add sidebar links under <code>themeConfig.sidebar[&#39;/replybridge/&#39;]</code> when you add many child pages.</p><p>When adding a new product section, follow existing app folder patterns and update <code>themeConfig.nav</code> if needed.</p><h2 id="documents-to-read-with-reply-bridge" tabindex="-1">Documents to read with reply-bridge <a class="header-anchor" href="#documents-to-read-with-reply-bridge" aria-hidden="true">#</a></h2><ul><li><code>reply-bridge/marketing/</code> — series copy, structure (<code>CARD_NEWS_STRUCTURE.md</code>, etc.).</li><li><code>reply-bridge/docs/PRODUCT.md</code>, <code>STACK.md</code>, <code>ARCHITECTURE.md</code> — product and technical alignment.</li><li>App Store / Meta wording: prefer matching MDs under <code>reply-bridge/docs/</code>.</li></ul><h2 id="style" tabindex="-1">Style <a class="header-anchor" href="#style" aria-hidden="true">#</a></h2><ul><li>No drive-by refactors or unrelated files.</li><li>Match existing Markdown tone, heading levels, and internal links.</li><li>For legal/policy text, align with reply-bridge marketing/policy docs when possible.</li></ul><h2 id="cursor-rules-outside-vitepress-docs" tabindex="-1">Cursor rules (outside VitePress <code>docs/</code>) <a class="header-anchor" href="#cursor-rules-outside-vitepress-docs" aria-hidden="true">#</a></h2><p>Repository root:</p><ul><li><code>.cursor/rules/workflow.mdc</code> — commits, issues, reply-bridge alignment.</li><li><code>.cursor/rules/vitepress-docs.mdc</code> — rules when editing VitePress <code>docs/</code>.</li></ul>',21),s=[i];function c(a,l,n,h,p,u){return d(),t("div",null,s)}const b=e(r,[["render",c]]);export{m as __pageData,b as default};
